// Bundle the inlined web build into expo-app/webBundle.ts so the Expo Go
// app can render it from source={{ html }} with no network dependency.
const fs = require('fs');
const path = require('path');

const htmlPath = path.join(__dirname, '..', 'web', 'dist', 'index.html');
const outPath = path.join(__dirname, '..', 'expo-app', 'webBundle.ts');

const html = fs.readFileSync(htmlPath, 'utf8');
if (!html.includes('<script type="module">')) {
  console.error('expo-bundle.cjs: web/dist/index.html is not inlined — run tools/inline.cjs first');
  process.exit(1);
}

const out =
  '/* Generated by tools/expo-bundle.cjs from web/dist/index.html — do not edit. */\n' +
  `export const WEB_HTML = ${JSON.stringify(html)};\n`;

fs.writeFileSync(outPath, out);
console.log(`expo-bundle.cjs: webBundle.ts <- ${html.length} bytes of HTML`);
